import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { _getHeadingVariant } from './empty-state-utils.js';
import { contentContainerCss, titleSlotCss } from './EmptyState.sty.js';
import { EmptyStateWrapper } from './EmptyStateWrapper.js';
import { _useEmptyStateSlots } from './hooks/use-empty-state-slots.js';
import { Actions } from './slot-components/Actions.js';
import { Details } from './slot-components/Details.js';
import { Footer } from './slot-components/Footer.js';
import { Title } from './slot-components/Title.js';
import { Visual } from './slot-components/Visual.js';
import { VisualPreset } from './slot-components/VisualPreset.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Divider } from '../../typography/Divider.js';
import { Heading } from '../../typography/Heading.js';

//#region Typings

export interface EmptyStateProps
  extends WithChildren,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * Size of the empty state component.
   * @defaultValue 'default'
   */
  size?: 'small' | 'default' | 'large';
}
//#endregion Typings

export const _EmptyState = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  EmptyStateProps
>((props, forwardedRef) => {
  const {
    size = 'default',
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  const slots = _useEmptyStateSlots(children);

  const hasDivider =
    (slots.Actions || slots.Details || slots.Title || slots.Visual) &&
    slots.Footer;

  return (
    <EmptyStateWrapper
      size={size}
      ref={forwardedRef}
      className={consumerClassName}
      data-testid={dataTestId}
      style={consumerStyle}
    >
      {slots.Visual && slots.Visual}
      <Flex
        className={clsx(contentContainerCss)}
        maxWidth={600}
        flexDirection="column"
      >
        {slots.Title && (
          <Heading {..._getHeadingVariant(size)} className={clsx(titleSlotCss)}>
            {slots.Title}
          </Heading>
        )}
        {slots.Details && slots.Details}
        {slots.Actions && slots.Actions}
        {hasDivider && <Divider />}
        {slots.Footer && slots.Footer}
      </Flex>
    </EmptyStateWrapper>
  );
});

export const EmptyState = Object.assign(_EmptyState, {
  Actions,
  Details,
  Footer,
  Title,
  Visual,
  VisualPreset,
});
